import{_ as r,C as l,o,c as i,a2 as n,b as s,w as e,a as g,E as d,a3 as A}from"./chunks/framework.DToEn73J.js";const B=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"AI Agent 工程入门","text":"面向资深工程师的设计资料站","tagline":"系统覆盖 Agent 工程核心主题 —— 去水分、直奔设计决策、每个知识点用「是什么 / 怎么做 / 为什么」三段式讲清。","actions":[{"theme":"brand","text":"从 Agent Loop 开始","link":"/01-agent-basics/agent-loop"},{"theme":"alt","text":"查看术语表","link":"/glossary"}]},"features":[{"icon":"🔁","title":"Agent 基础架构","details":"Agent Loop、工具抽象、结构化输出与函数调用、终止条件与预算控制、并发与竞态。","link":"/01-agent-basics/agent-loop","linkText":"第一章"},{"icon":"🧩","title":"能力扩展机制","details":"Skill 加载与管理、MCP 加载与扩展、权限与沙箱、多 Agent 编排与子 Agent 委派。","link":"/02-capability-extension/skill-management","linkText":"第二章"},{"icon":"🧠","title":"上下文与记忆","details":"上下文工程、上下文窗口管理、长期记忆管理、状态与会话持久化、RAG 检索增强。","link":"/03-context-memory/context-engineering","linkText":"第三章"},{"icon":"🗺️","title":"规划与执行","details":"Plan-and-Execute 模式切换、任务列表管理、错误处理与自我修正、模型路由与多模型编排。","link":"/04-planning-execution/plan-and-execute","linkText":"第四章"},{"icon":"🛡️","title":"安全与治理","details":"Prompt 防注入、审计和回滚、安全护栏与内容审核、紧急停止机制。","link":"/05-safety-governance/prompt-injection","linkText":"第五章"},{"icon":"⚙️","title":"工程化与运维","details":"Prompt 管理、可观测性（OTEL + Langfuse）、可评估性、成本与延迟优化、部署与扩展性。","link":"/06-engineering-ops/prompt-management","linkText":"第六章"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788255095000}'),c={name:"index.md"};function h(E,t,p,u,m,k){const a=l("Mermaid");return o(),i("div",null,[t[1]||(t[1]=n('<h2 id="我「独立发明」过的七个轮子" tabindex="-1">我「独立发明」过的七个轮子 <a class="header-anchor" href="#我「独立发明」过的七个轮子" aria-label="Permalink to &quot;我「独立发明」过的七个轮子&quot;">​</a></h2><p>坦白讲，下面这些机制，我当年都是凭直觉先自己造了一遍土办法，后来查了查资料才发现——原来它们早就有高大上的名字。先上一张总表，正文再逐个展开。</p><table tabindex="0"><thead><tr><th>我的土办法（当时是这么想的）</th><th>后来才知道，这叫</th></tr></thead><tbody><tr><td>大模型（API）其实是个无状态的东西。它所谓的记忆，就是在你每次提问时，把在此之前你和它的所有对话一股脑打包发给它</td><td><strong>上下文 / 记忆</strong>（无状态 API + 历史打包）</td></tr><tr><td>在提示词里给大模型举几个例子</td><td><strong>Few-Shot</strong>（In-Context Learning）</td></tr><tr><td>搜点参考文献，让大模型在回答前看看</td><td><strong>RAG</strong>（Retrieval-Augmented Generation）</td></tr><tr><td>让大模型按格式输出一段 JSON 文本，后端解析这段 JSON，运行大模型希望运行的工具函数</td><td><strong>Tool Calling</strong>（Function Calling）</td></tr><tr><td>让大模型先思考需求，再调用工具，再观察工具调用结果，如此循环往复，直到它觉得自己能回答问题</td><td><strong>ReAct</strong>（Reason + Act）</td></tr><tr><td>让大模型通过 Tool Calling 直接调用搜索函数，自己决定自己想搜什么</td><td><strong>Agentic RAG</strong></td></tr><tr><td>一段 system prompt，但是只给大模型看个摘要，让大模型想读再读</td><td><strong>Skill</strong>（渐进式披露）</td></tr></tbody></table><p>下面按「从地基到封装」的顺序逐个展开——它们不是七个并列的名词，而是一条演化链。</p><h3 id="_1-上下文-记忆-——-大模型-api-是无状态的" tabindex="-1">1. 上下文 / 记忆 —— 大模型 API 是无状态的 <a class="header-anchor" href="#_1-上下文-记忆-——-大模型-api-是无状态的" aria-label="Permalink to &quot;1. 上下文 / 记忆 —— 大模型 API 是无状态的&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：其实大模型（API）是个无状态的东西，它所谓的记忆，就是在你每次提问的时候，把在此之前你和它的所有对话，一股脑打包发给它。</p></blockquote><ul><li><strong>是什么</strong>：API 就是个纯函数——塞进去一个 messages 数组，吐出来一条回复，什么也不保存。「记得你」是客户端的功劳，不是它的。</li><li><strong>核心机制</strong>：每轮把 system / user / assistant / tool 消息按序全量重发；这个包的容量上限就是 Context Window，装不下就得裁剪或者做摘要。</li><li><strong>应用场景</strong>：多轮对话、会话持久化、长期记忆系统——本质都是你在替模型管历史。</li><li><strong>联系与区别</strong>：这是其余六个概念的地基——Few-Shot 和 RAG 研究往这个包里<strong>塞什么</strong>，Tool Calling 研究从包里<strong>掏什么</strong>出来。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/context-window">上下文窗口管理</a>、<a href="/fk-ai-agent/03-context-memory/session-state">状态与会话持久化</a></li></ul><h3 id="_2-few-shot-——-在提示词里举几个例子" tabindex="-1">2. Few-Shot —— 在提示词里举几个例子 <a class="header-anchor" href="#_2-few-shot-——-在提示词里举几个例子" aria-label="Permalink to &quot;2. Few-Shot —— 在提示词里举几个例子&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：在提示词里给大模型举几个例子。（就这么简单。后来发现这叫 In-Context Learning，GPT-3 那篇论文的标题就是它。）</p></blockquote><ul><li><strong>是什么</strong>：不动权重，直接在 prompt 里放 K 个输入/输出示例，模型照葫芦画瓢（K=0 就是 Zero-Shot）。</li><li><strong>核心机制</strong>：例子选得好不好、放几个、放前面还是后面，效果差很多；例子本身也要吃 token 预算。</li><li><strong>应用场景</strong>：让输出守格式、对齐风格、分类任务冷启动、结构化抽取。</li><li><strong>联系与区别</strong>：跟微调相对——不动权重、即改即生效、按 token 付钱；跟 RAG 是一路的（都是往上下文里塞东西），只是塞的是<strong>人挑的例子</strong>，不是检索出来的知识。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/context-engineering">上下文工程</a></li></ul><h3 id="_3-rag-——-搜点参考文献-回答前先看看" tabindex="-1">3. RAG —— 搜点参考文献，回答前先看看 <a class="header-anchor" href="#_3-rag-——-搜点参考文献-回答前先看看" aria-label="Permalink to &quot;3. RAG —— 搜点参考文献，回答前先看看&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：搜点参考文献，让大模型在回答前看看。</p></blockquote><ul><li><strong>是什么</strong>：先检索再生成——把命中的材料塞进 prompt，让模型「开卷考试」。</li><li><strong>核心机制</strong>：离线：文档切块、做 embedding、进向量库；在线：用 query 检索最相关的几块，塞进上下文。</li><li><strong>应用场景</strong>：私有知识问答、长文档问答、需要给出处的场景。</li><li><strong>联系与区别</strong>：解决「知识在窗口外面」的问题。注意它的检索是<strong>固定流水线</strong>——查一次、答一次，这正是它和 Agentic RAG 的分界线。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/rag">RAG 检索增强</a></li></ul><h3 id="_4-tool-calling-——-让模型输出-json-后端照着执行" tabindex="-1">4. Tool Calling —— 让模型输出 JSON，后端照着执行 <a class="header-anchor" href="#_4-tool-calling-——-让模型输出-json-后端照着执行" aria-label="Permalink to &quot;4. Tool Calling —— 让模型输出 JSON，后端照着执行&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：让大模型按格式输出一段 JSON 文本，然后后端解析这段 JSON 文本，运行大模型希望运行的工具函数。</p></blockquote><ul><li><strong>是什么</strong>：给模型一份工具清单（名字 + 说明 + 参数的 JSON Schema），模型回答时不说话，改输出「我要调这个函数、参数是这些」；真正执行永远在你的后端。</li><li><strong>核心机制</strong>：工具注册表注入上下文 → 模型输出 tool call → 你的代码解析并执行 → 结果作为 tool 消息喂回去。</li><li><strong>应用场景</strong>：查数据库、调 API、写文件、发消息——一切模型需要「动手」的场景。</li><li><strong>联系与区别</strong>：Few-Shot / RAG 管输入侧，这个管<strong>输出侧</strong>。单次调用就能成立，但要干多步的活，得有人把它放进循环——那就轮到 ReAct 了。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/01-agent-basics/structured-output">结构化输出与函数调用</a>、<a href="/fk-ai-agent/01-agent-basics/tool-abstraction">工具抽象</a></li></ul><h3 id="_5-react-——-思考、行动、观察-循环往复" tabindex="-1">5. ReAct —— 思考、行动、观察，循环往复 <a class="header-anchor" href="#_5-react-——-思考、行动、观察-循环往复" aria-label="Permalink to &quot;5. ReAct —— 思考、行动、观察，循环往复&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：让大模型先思考需求，再调用工具，再观察工具调用结果，如此循环往复，直到它觉得自己能回答问题。</p></blockquote><ul><li><strong>是什么</strong>：Reason + Act——模型在「想（Thought）→ 做（Action）→ 看（Observation）」之间循环，直到它认为能给出最终答案。</li><li><strong>核心机制</strong>：循环 + 终止条件。工程上必须配 max_steps、预算、超时、重复调用检测，不然就是死循环制造机。</li><li><strong>应用场景</strong>：一切 Agent 框架的运行时内核——无论框架叫什么名字，都逃不出这个循环（Agent Loop）。</li><li><strong>联系与区别</strong>：Tool Calling 是<strong>一次调用的协议</strong>，ReAct 是<strong>反复调用的骨架</strong>；再往上加规划、任务列表、委派，就是 Plan-and-Execute 和多 Agent 编排。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/01-agent-basics/agent-loop">Agent Loop</a>、<a href="/fk-ai-agent/04-planning-execution/plan-and-execute">Plan-and-Execute</a></li></ul><h3 id="_6-agentic-rag-——-搜索变成模型自己的工具" tabindex="-1">6. Agentic RAG —— 搜索变成模型自己的工具 <a class="header-anchor" href="#_6-agentic-rag-——-搜索变成模型自己的工具" aria-label="Permalink to &quot;6. Agentic RAG —— 搜索变成模型自己的工具&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：让大模型通过 Tool Calling 直接调用搜索函数，自己决定自己想搜什么。</p></blockquote><ul><li><strong>是什么</strong>：把「搜索」降格为 Agent 的一个普通工具——什么时候搜、搜什么、搜完不够再搜什么，全由模型自己决定。</li><li><strong>核心机制</strong>：朴素 RAG 的固定流水线（查一次 → 答一次）升级为动态决策：可多次检索、可改写 query、可判定「材料不够」继续补查。</li><li><strong>应用场景</strong>：多跳问题（答案散落在多个文档里）、研究型问答、跨数据源聚合。</li><li><strong>联系与区别</strong>：一句话——<strong>Agentic RAG = RAG + ReAct</strong>：知识注入策略装进循环骨架。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/rag">RAG 检索增强</a>、<a href="/fk-ai-agent/01-agent-basics/agent-loop">Agent Loop</a></li></ul><h3 id="_7-skill-——-一段-system-prompt-先看摘要-想读再读" tabindex="-1">7. Skill —— 一段 system prompt，先看摘要，想读再读 <a class="header-anchor" href="#_7-skill-——-一段-system-prompt-先看摘要-想读再读" aria-label="Permalink to &quot;7. Skill —— 一段 system prompt，先看摘要，想读再读&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：一段 system prompt，但是只给大模型看个摘要，让大模型想读再读。</p></blockquote><ul><li><strong>是什么</strong>：把某类任务的提示词、工具说明、参考资料打包成一个独立文件，平时只露一个摘要，模型觉得需要时才加载全文。</li><li><strong>核心机制</strong>：先只注入名字 + 简介（几个 token），按需再展开——官方管这叫「渐进式披露」（progressive disclosure）。解决「能力太多、窗口太小」的矛盾。</li><li><strong>应用场景</strong>：Agent 能力插件化——代码审查、数据分析各有各的 Skill，互不污染上下文。</li><li><strong>联系与区别</strong>：Tool 是模型的「手」，Skill 是教它「怎么用手干这类活」的说明书；和 MCP 互补——MCP 管工具<strong>接入</strong>协议，Skill 管知识/流程的<strong>封装复用</strong>。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/02-capability-extension/skill-management">Skill 加载与管理</a>、<a href="/fk-ai-agent/02-capability-extension/mcp">MCP 加载与扩展</a></li></ul><h3 id="七个概念-一张图" tabindex="-1">七个概念，一张图 <a class="header-anchor" href="#七个概念-一张图" aria-label="Permalink to &quot;七个概念，一张图&quot;">​</a></h3>',26)),(o(),s(A,null,{default:e(()=>[d(a,{id:"mermaid-328",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20C%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E7%AA%97%E5%8F%A3%3Cbr%2F%3E%EF%BC%88%E6%97%A0%E7%8A%B6%E6%80%81%20API%20%2B%20%E5%8E%86%E5%8F%B2%E6%89%93%E5%8C%85%EF%BC%89%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E5%BE%80%E9%87%8C%E5%A1%9E%E4%BB%80%E4%B9%88%22%7C%20F%5B%22Few-Shot%3Cbr%2F%3E%E6%B3%A8%E5%85%A5%E7%A4%BA%E4%BE%8B%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E5%BE%80%E9%87%8C%E5%A1%9E%E4%BB%80%E4%B9%88%22%7C%20R%5B%22RAG%3Cbr%2F%3E%E6%B3%A8%E5%85%A5%E6%A3%80%E7%B4%A2%E7%9F%A5%E8%AF%86%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E4%BB%8E%E4%B8%AD%E5%8F%96%E4%BB%80%E4%B9%88%22%7C%20T%5B%22Tool%20Calling%3Cbr%2F%3E%E8%BE%93%E5%87%BA%E7%BB%93%E6%9E%84%E5%8C%96%E8%B0%83%E7%94%A8%22%5D%0A%20%20%20%20T%20--%3E%7C%22%E6%94%BE%E8%BF%9B%E5%BE%AA%E7%8E%AF%22%7C%20A%5B%22ReAct%20%2F%20Agent%20Loop%22%5D%0A%20%20%20%20R%20--%3E%20A%0A%20%20%20%20A%20--%3E%20AR%5B%22Agentic%20RAG%3Cbr%2F%3E%3D%20RAG%20%2B%20ReAct%22%5D%0A%20%20%20%20R%20--%3E%20AR%0A%20%20%20%20A%20--%3E%20S%5B%22Skill%EF%BC%9A%E6%8F%90%E7%A4%BA%E8%AF%8D%20%2B%20%E5%B7%A5%E5%85%B7%20%2B%20%E6%B5%81%E7%A8%8B%3Cbr%2F%3E%E6%89%93%E5%8C%85%E6%87%92%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20%20%20F%20--%3E%20S%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=n('<h3 id="速查表-区别与联系" tabindex="-1">速查表：区别与联系 <a class="header-anchor" href="#速查表-区别与联系" aria-label="Permalink to &quot;速查表：区别与联系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>解决的问题</th><th>所在层次</th><th>一句话联系</th></tr></thead><tbody><tr><td>上下文 / 记忆</td><td>API 无状态，「记忆」要自己打包</td><td>地基</td><td>其余六个概念的前提</td></tr><tr><td>Few-Shot</td><td>光靠指令说不清任务</td><td>输入侧 · 静态</td><td>往窗口里塞示例</td></tr><tr><td>RAG</td><td>知识在窗口外</td><td>输入侧 · 动态</td><td>往窗口里塞检索结果</td></tr><tr><td>Tool Calling</td><td>模型无法直接作用于外界</td><td>输出侧 · 协议</td><td>从窗口里取调用意图</td></tr><tr><td>ReAct</td><td>单次调用完不成多步任务</td><td>运行时 · 循环</td><td>Tool Calling × 循环</td></tr><tr><td>Agentic RAG</td><td>固定检索流水线不够聪明</td><td>组合模式</td><td>RAG + ReAct</td></tr><tr><td>Skill</td><td>能力总量远超窗口容量</td><td>封装复用层</td><td>提示词 / 工具 / 流程打包</td></tr></tbody></table><h2 id="这个站点是什么" tabindex="-1">这个站点是什么 <a class="header-anchor" href="#这个站点是什么" aria-label="Permalink to &quot;这个站点是什么&quot;">​</a></h2><p>本站是一份<strong>工程向</strong>的 AI Agent 设计资料，面向已有分布式系统、算法与基本 ML/LLM 背景的工程师。不解释「什么是 API」「什么是向量」这类基础概念，只聚焦 Agent 领域特有的设计决策与权衡。</p><p>全站按「从内到外」的工程分层组织为 6 章、24 个主题页，外加术语表与架构决策矩阵速查页。建议先按章节顺序通读，再用决策矩阵做索引式回顾。</p><h2 id="内容规范" tabindex="-1">内容规范 <a class="header-anchor" href="#内容规范" aria-label="Permalink to &quot;内容规范&quot;">​</a></h2><p>每个主题页统一采用三段式：</p><ol><li><strong>是什么</strong> —— 1–2 句定义问题域，不铺垫。</li><li><strong>怎么做</strong> —— 关键技术选择 + 最小可用实现思路，对比用表格、流程用 Mermaid 图。</li><li><strong>为什么</strong> —— 不这样做的后果，或与替代方案的权衡。</li></ol><p>涉及协议 / 规范 / 基准版本（如 MCP、OTEL + Langfuse、SWE-bench）的页面已 web search 核实当前版本，并在页底标注「最后核实日期」。</p>',9))])}const x=r(c,[["render",h]]);export{B as __pageData,x as default};
